<?php
declare(strict_types=1);

use DigiForge\Database\Tables;
use DigiForge\Listings\EtsyControlledHttpExecutor;

/** Synthetic credentials and injected responses; never authentic provider certification. */
final class EtsyControlledTransportAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 private function prepared():array {
  global $wpdb;$now=current_time('mysql',true);self::assertSame(1,$wpdb->insert(Tables::integrations(),['provider'=>'etsy','connection_key'=>'controlled-'.wp_rand(),'display_name'=>'Synthetic transport fixture','config'=>'{}','environment'=>'sandbox','created_at'=>$now,'updated_at'=>$now]));$id=(int)$wpdb->insert_id;
  foreach(['access_token','keystring','shared_secret']as $name){$plain='offline-only-'.$name;$cipher=DigiForge\Integrations\CredentialVault::encrypt($plain,DigiForge\Integrations\Repository::secretContext($id,$name));self::assertSame(1,$wpdb->insert(Tables::integration_secrets(),['integration_id'=>$id,'secret_name'=>$name,'ciphertext'=>$cipher,'fingerprint'=>substr(hash('sha256',$plain),0,16),'created_at'=>$now,'updated_at'=>$now]));}
  $hash=hash('sha256',wp_generate_uuid4());self::assertSame(1,$wpdb->insert(Tables::listings(),['product_version_id'=>1,'environment'=>'sandbox','shop_reference'=>'digital','title'=>'Synthetic transport scope','state'=>'APPROVED','approved_by'=>get_current_user_id(),'approved_at'=>$now,'created_at'=>$now,'updated_at'=>$now]));$listing=(int)$wpdb->insert_id;
  self::assertSame(1,$wpdb->insert(Tables::etsy_draft_packages(),['listing_id'=>$listing,'package_version'=>'v1','canonical_payload'=>'{}','payload_hash'=>$hash,'readiness'=>'{}','readiness_hash'=>$hash,'approved_by'=>get_current_user_id(),'approved_at'=>$now,'created_at'=>$now]));$package=(int)$wpdb->insert_id;
  self::assertSame(1,$wpdb->insert(Tables::etsy_intents(),['listing_id'=>$listing,'draft_package_id'=>$package,'environment'=>'sandbox','intent_type'=>'PREPARE_DRAFT','state'=>'APPROVED_INTENT','created_at'=>$now,'updated_at'=>$now]));$intent=(int)$wpdb->insert_id;$payload=['title'=>'Offline fixture','quantity'=>1];$operation=(new DigiForge\Listings\EtsyOperationRepository())->createFromPayload(['shop_reference'=>'digital','intent_id'=>$intent,'draft_package_id'=>$package,'operation_type'=>'CREATE_DRAFT','idempotency_key'=>'transport-'.wp_generate_uuid4(),'authorization_hash'=>$hash,'evidence_hash'=>$hash],$payload);self::assertNotWPError($operation);$op=(int)$operation['id'];
  $scope=['state'=>'ETSY_SCOPED_CREDENTIAL_ACCESS_AUTHORIZED','single_use'=>true,'credential_name'=>'access_token','general_credential_access'=>false,'refresh_token_access'=>false,'credential_persistence_permitted'=>false,'credential_logging_permitted'=>false,'credential_retrieval_performed'=>false,'network_request_permitted'=>false,'external_execution_performed'=>false,'integration_id'=>$id,'operation_id'=>$op];
  return ['state'=>'ETSY_CONTROLLED_TRANSPORT_PREPARED','operation_id'=>$op,'integration_id'=>$id,'operation_type'=>'CREATE_DRAFT','network_request_permitted'=>false,'network_request_attempted'=>false,'external_execution_performed'=>false,'transport'=>['state'=>'ETSY_CREDENTIAL_AWARE_TRANSPORT_PREPARED','credential_retrieval_deferred'=>true,'credential_scope'=>$scope],'request_plan'=>['method'=>'POST','endpoint'=>'/application/shops/123/listings','headers'=>['Content-Type'=>'application/x-www-form-urlencoded'],'payload'=>$payload]];
 }
 private function simulatedInterlock(callable $work):mixed {
  // This override exists only while the injected sender executes. Stored controls stay protected.
  $values=['activation_authorized'=>true,'automation_armed'=>true,'stop_all'=>false,'etsy_draft'=>true,'etsy_draft_activation_authorized'=>true];$table=Tables::settings();
  $query=static function(string $sql)use($values,$table):string{foreach($values as $key=>$value){if(str_contains($sql,'SELECT setting_value, setting_type FROM '.$table)&&str_contains($sql,"setting_key = '".$key."'")){return "SELECT '".($value?'true':'false')."' AS setting_value, '".DigiForge\Core\Config::setting_type($key)."' AS setting_type";}}return $sql;};
  $http=static fn()=>new WP_Error('offline_transport','Actual HTTP forbidden.');add_filter('query',$query);add_filter('pre_http_request',$http);
  try{return $work();}finally{remove_filter('query',$query);remove_filter('pre_http_request',$http);}
 }
 public function testNonMultipartInjectedSenderExecutesWithoutUndefinedVariablesAndKeepsCredentialsOutOfResult():void {
  $prepared=$this->prepared();$calls=0;$executor=new EtsyControlledHttpExecutor(static function(string $url,array $args)use(&$calls):array{$calls++;self::assertSame('https://openapi.etsy.com/v3/application/shops/123/listings',$url);self::assertStringNotContainsString('offline-only',$url);self::assertSame('Bearer offline-only-access_token',$args['headers']['Authorization']);self::assertSame('title=Offline%20fixture&quantity=1',$args['body']);return ['response'=>['code'=>201],'headers'=>['Retry-After'=>'9','X-Limit-Per-Second'=>'5'],'body'=>'{"listing_id":8801}'];});
  $result=$this->simulatedInterlock(function()use($prepared,$executor){$authorized=DigiForge\Listings\EtsyLiveTransportInterlock::authorize($prepared);self::assertNotWPError($authorized);return $executor->execute($prepared,$authorized);});
  self::assertNotWPError($result);self::assertSame(1,$calls);self::assertSame('8801',$result['external_reference']);self::assertSame(9,$result['rate_limit']['retry_after_seconds']);self::assertSame(5,$result['rate_limit']['limit_per_second']);self::assertFalse($result['rate_limit']['retry_scheduled']);self::assertStringNotContainsString('offline-only',(string)wp_json_encode($result));self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(DigiForge\Core\Settings::safety_locked());
  global $wpdb;$stored=json_decode((string)$wpdb->get_var($wpdb->prepare('SELECT context FROM '.Tables::audit_log().' WHERE event_type=%s AND object_type=%s AND object_id=%s ORDER BY id DESC LIMIT 1','etsy_external_attempt_recorded','etsy_operation',(string)$prepared['operation_id'])),true);self::assertSame($result['attempt']['attempt_id'],$stored['attempt_id']);self::assertSame(9,$stored['rate_limit']['retry_after_seconds']);self::assertStringNotContainsString('offline-only',(string)wp_json_encode($stored));
  $lifecycle=(new DigiForge\Listings\EtsyAttemptLifecycleService(new DigiForge\Listings\EtsyOperationRepository()))->record(['state'=>'ETSY_ADAPTER_INVOCATION_PLANNED','operation_id'=>$prepared['operation_id']],$result);self::assertNotWPError($lifecycle);self::assertSame('CONFIRMED_SUCCESS',$lifecycle['outcome']['operation']['state']);self::assertSame('8801',$lifecycle['outcome']['operation']['external_reference']);
 }
 public function testProtectedInterlockDeniesBeforeCredentialReadOrSenderAndIdentityMismatchCannotBorrowScope():void {
  $prepared=$this->prepared();$calls=0;$reads=0;$table=Tables::integration_secrets();$observe=static function(string $sql)use(&$reads,$table):string{if(str_contains($sql,'FROM '.$table))$reads++;return $sql;};$executor=new EtsyControlledHttpExecutor(static function()use(&$calls){$calls++;return [];});$authorized=['state'=>'ETSY_LIVE_TRANSPORT_AUTHORIZED','network_request_permitted'=>true,'network_request_attempted'=>false,'operation_id'=>$prepared['operation_id'],'integration_id'=>$prepared['integration_id']];
  add_filter('query',$observe);try{$result=$executor->execute($prepared,$authorized);self::assertWPError($result);self::assertSame('digiforge_etsy_live_transport_locked',$result->get_error_code());$authorized['operation_id']++;self::assertWPError($executor->execute($prepared,$authorized));}finally{remove_filter('query',$observe);}self::assertSame(0,$reads);self::assertSame(0,$calls);
 }
}
